```tsx
import "./ChecklistItem.css";

export interface ChecklistItemProps {
  title: string;
  detail: string;
  minutes: number;
  done: boolean;
  onToggle: () => void;
}

export function ChecklistItem({
  title,
  detail,
  minutes,
  done,
  onToggle,
}: ChecklistItemProps) {
  const rowClass = done
    ? "checklist-item checklist-item--done"
    : "checklist-item";

  return (
    <div className={rowClass}>
      <button
        type="button"
        className="checklist-item__check"
        aria-pressed={done}
        aria-label={`Done: ${title}`}
        onClick={onToggle}
      >
        <svg
          className="checklist-item__icon"
          viewBox="0 0 16 16"
          aria-hidden="true"
          focusable="false"
        >
          <path d="M3.5 8.5l3 3 6-7" />
        </svg>
      </button>

      <div className="checklist-item__text">
        <p className="checklist-item__title">{title}</p>
        {detail !== "" && <p className="checklist-item__detail">{detail}</p>}
      </div>

      <span className="checklist-item__minutes">{minutes} min</span>
    </div>
  );
}
```

