.checklist-item {
  display: flex;
  align-items: center;
  gap: clamp(0.6rem, 1.5vw, 1rem);
  padding: clamp(0.6rem, 1.4vw, 0.9rem) 0;
  border-bottom: 1px solid var(--hair);
  color: var(--ink);
}

.checklist-item__check {
  flex: none;
  display: grid;
  place-items: center;
  width: clamp(1.75rem, 3vw, 2.25rem);
  aspect-ratio: 1;
  padding: 0;
  border-radius: 50%;
  border: 2px solid var(--muted);
  background: transparent;
  color: var(--slide);
  font: inherit;
  cursor: pointer;
  transition: background-color 160ms ease, border-color 160ms ease;
}

.checklist-item__check:hover {
  background: var(--myelin-wash);
  border-color: var(--myelin);
}

.checklist-item__check[aria-pressed="true"] {
  background: var(--myelin);
  border-color: var(--myelin);
}

.checklist-item__check[aria-pressed="false"] .checklist-item__icon {
  visibility: hidden;
}

.checklist-item__icon {
  width: 60%;
  height: 60%;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.25;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.checklist-item__text {
  flex: 1 1 auto;
  min-width: 0;
}

.checklist-item__title {
  margin: 0;
  color: var(--ink);
  font-size: clamp(0.95rem, 1.2vw + 0.6rem, 1.15rem);
  overflow-wrap: anywhere;
}

.checklist-item__detail {
  margin: 0.15rem 0 0;
  color: var(--muted);
  font-size: clamp(0.8rem, 0.9vw + 0.4rem, 0.95rem);
  overflow-wrap: anywhere;
}

.checklist-item__minutes {
  flex: none;
  color: var(--muted);
  font-size: clamp(0.8rem, 0.9vw + 0.4rem, 0.95rem);
  font-variant-numeric: tabular-nums;
}

.checklist-item--done .checklist-item__title {
  color: var(--muted);
  text-decoration: line-through;
}

:root[data-motion="reduce"] .checklist-item__check {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .checklist-item__check {
    transition: none;
  }
}
```

